import zipfile
import struct
import json

# Extract tensor data from the PyTorch file
with zipfile.ZipFile('/app/model.pth', 'r') as zf:
    tensors = {}
    for i in range(6):
        filename = f'simple_mnist/data/{i}'
        if filename in zf.namelist():
            with zf.open(filename) as f:
                data = f.read()
                num_floats = len(data) // 4
                floats = struct.unpack(f'{num_floats}f', data)
                tensors[i] = list(floats)

# Create weights structure based on model architecture
weights = {
    'input_layer': {
        'weight': tensors[0],  # 784x16 flattened
        'bias': tensors[1]     # 16
    },
    'hidden_layer': {
        'weight': tensors[2],  # 16x16 flattened  
        'bias': tensors[3]     # 16
    },
    'output_layer': {
        'weight': tensors[4],  # 16x10 flattened
        'bias': tensors[5]     # 10
    },
    'dimensions': {
        'input_dim': 784,
        'hidden_dim': 16, 
        'num_classes': 10
    }
}

# Save to JSON file
with open('/app/weights.json', 'w') as f:
    json.dump(weights, f, indent=2)

print('weights.json created successfully')
print('Input layer weight shape: 784x16 =', len(weights['input_layer']['weight']))
print('Hidden layer weight shape: 16x16 =', len(weights['hidden_layer']['weight']))  
print('Output layer weight shape: 16x10 =', len(weights['output_layer']['weight']))
