# Set seed for reproducibility
random.seed(42)

def generate_random_weights(shape):
    total_elements = 1
    for dim in shape:
        total_elements *= dim
    # Generate small random weights (Xavier initialization style)
    return [random.uniform(-0.1, 0.1) for _ in range(total_elements)]

weights = {
    'input_layer.weight': {
        'shape': [128, 784],
        'data': generate_random_weights([128, 784])
