import os, signal, time, glob
# Kill processes using ports
for port in [8888, 8889, 8890, 8891]:
    try:
        for line in os.popen(f'lsof -i :{port} 2>/dev/null || echo').readlines():
            if 'python' in line:
                pid = int(line.split()[1])
                try:
                    os.kill(pid, signal.SIGKILL)
                    print(f'Killed process {pid} on port {port}')
                except:
                    pass
    except:
        pass
time.sleep(3)
# Also try to find jupyter processes in /proc
for proc_dir in glob.glob('/proc/[0-9]*'):
    try:
        with open(f'{proc_dir}/cmdline', 'r') as f:
            cmdline = f.read()
            if 'jupyter' in cmdline and 'notebook' in cmdline:
                pid = int(os.path.basename(proc_dir))
                os.kill(pid, signal.SIGKILL)
                print(f'Killed jupyter process {pid}')
    except:
        pass
print('Done killing processes')
